/* =========================
   A TEAM DASHBOARD - app.js
   MULTI-AGENT + TASK-AWARE UI
   ========================= */

const map = document.querySelector(".map");
const ORIGIN = window.location.origin;
const BACKEND_URL =
  window.ATEAM_BACKEND_URL ||
  localStorage.getItem("ATEAM_BACKEND_URL") ||
  (ORIGIN.includes("localhost:3000") || ORIGIN.includes("127.0.0.1:3000")
    ? ORIGIN
    : "http://localhost:3000");

/* ROOMS */
const rooms = {
  apps: document.getElementById("apps-room"),
  jobs: document.getElementById("jobs-room"),
  learning: document.getElementById("learning-room"),
  strategy: document.getElementById("strategy-room"),
};

/* AGENTS */
const agents = {
  coach: document.getElementById("coach"),
  builder: document.getElementById("builder"),
  scout: document.getElementById("scout"),
  thinker: document.getElementById("thinker"),
};

/* TASK CARDS */
const taskCards = document.querySelectorAll(".task-card");
let activeTaskId = "global";
let activeRoomId = "global"; // new: track current room for room-level memory
let activePersonalId = "user"; // new: fixed personal id for now

/* =========================
   TASK ID HELPERS
   ========================= */

function slugify(str) {
  return String(str || "")
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-_]/g, "");
}

function stableTaskIdFromCard(card) {
  if (card.dataset.id) return card.dataset.id;

  const titleEl = card.querySelector(".task-title");
  const metaEl = card.querySelector(".task-meta");

  const title = titleEl ? titleEl.textContent : card.textContent;
  const meta = metaEl ? metaEl.textContent : "";

  const id = `task_${slugify(title)}_${slugify(meta)}`.slice(0, 120) || "global";
  card.dataset.id = id;
  return id;
}

function getActiveTaskCard() {
  return document.querySelector(".task-card.active-task");
}

function getActiveTaskText() {
  const card = getActiveTaskCard();
  if (!card) return "current task";
  return card.innerText.trim();
}

/* =========================
   AGENT HELPERS
   ========================= */

function getActiveAgentName() {
  if (agents.builder.classList.contains("active-agent")) return "Builder";
  if (agents.scout.classList.contains("active-agent")) return "Scout";
  if (agents.thinker.classList.contains("active-agent")) return "Think Tank";
  return "Coach";
}

/* =========================
   THREAD STORAGE - HIERARCHICAL MEMORY
   ========================= */

// Fetch thread messages for a given layer and id
async function fetchThreadLayer(layer, id) {
  try {
    const res = await fetch(
      `${BACKEND_URL}/task/thread/${encodeURIComponent(layer)}/${encodeURIComponent(id)}`
    );
    if (!res.ok) return [];
    const data = await res.json();
    if (Array.isArray(data)) return data;
    if (Array.isArray(data.thread)) return data.thread;
    return [];
  } catch {
    return [];
  }
}

// Fetch combined thread from all layers: global, room, personal
async function fetchTaskThread(taskId) {
  // taskId is the active task id (e.g. "global" or specific task)
  // Use activeRoomId and activePersonalId for room and personal layers
  const tid = taskId || "global";

  // Fetch all layers in parallel
  const [globalThread, roomThread, personalThread] = await Promise.all([
    fetchThreadLayer("global", tid),
    fetchThreadLayer("room", activeRoomId),
    fetchThreadLayer("personal", activePersonalId),
  ]);

  // Combine threads in order: global < room < personal
  // Personal messages override room and global context if needed
  // For now, just concatenate with layer tags for clarity
  const combined = [];

  globalThread.forEach((msg) => {
    combined.push({ ...msg, _layer: "global" });
  });
  roomThread.forEach((msg) => {
    combined.push({ ...msg, _layer: "room" });
  });
  personalThread.forEach((msg) => {
    combined.push({ ...msg, _layer: "personal" });
  });

  return combined;
}

// Append message specifying layer context
async function appendMessageToBackend(taskId, role, agent, content, layer = "global") {
  const tid = taskId || "global";
  const text = String(content || "");

  try {
    const res = await fetch(`${BACKEND_URL}/task/thread`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        taskId: tid,
        role: role || "user",
        agent: agent || "",
        content: text,
        layer: layer, // new field to specify memory layer
        // Backward safety
        message: text,
      }),
    });

    if (!res.ok) {
      const txt = await res.text();
      console.error("Thread sync failed:", res.status, txt);
    }
  } catch (err) {
    console.error("Failed to sync thread:", err);
  }
}

/* =========================
   VISUAL HELPERS
   ========================= */

function clearRoomGlow() {
  Object.values(rooms).forEach((room) => room.classList.remove("active-room"));
}

function clearAgentGlow() {
  Object.values(agents).forEach((agent) => agent.classList.remove("active-agent"));
}

function clearTaskHighlights() {
  taskCards.forEach((card) => card.classList.remove("active-task"));
}

// role-aware label styling without touching CSS yet
function renderLine(div, role, label, text, layer) {
  if (role === "system") {
    div.textContent = `• ${text}`;
    div.style.opacity = "0.75";
    div.style.fontSize = "0.92em";
    div.style.fontStyle = "italic";
    return;
  }

  if (role === "user") {
    div.textContent = `> ${text}`;
    return;
  }

  // Add layer tag for clarity
  const layerTag = layer ? ` [${layer}]` : "";
  div.textContent = `${label}${layerTag}: ${text}`;
}

function displayThread(thread) {
  const commandLog = document.getElementById("ai-command-log");
  commandLog.innerHTML = "";

  thread.forEach((msg) => {
    const div = document.createElement("div");

    if (typeof msg === "string") {
      div.textContent = msg;
      commandLog.appendChild(div);
      return;
    }

    const role = (msg.role || "").toLowerCase();
    const content = msg.content || msg.message || "";
    const label =
      msg.agent && String(msg.agent).trim()
        ? String(msg.agent).trim()
        : role === "assistant"
        ? "Coach"
        : "System";

    renderLine(div, role, label, content, msg._layer);
    commandLog.appendChild(div);
  });

  commandLog.scrollTop = commandLog.scrollHeight;
}

async function refreshThread(taskId) {
  const thread = await fetchTaskThread(taskId || "global");
  displayThread(thread);
}

/* =========================
   MOVE AGENT
   ========================= */

function moveAgent(agentEl, roomEl, taskCard = null) {
  const rect = roomEl.getBoundingClientRect();
  const mapRect = map.getBoundingClientRect();

  agentEl.style.left = rect.left - mapRect.left + 40 + "px";
  agentEl.style.top = rect.top - mapRect.top + 40 + "px";

  clearRoomGlow();
  clearAgentGlow();
  clearTaskHighlights();

  roomEl.classList.add("active-room");
  agentEl.classList.add("active-agent");

  if (taskCard) {
    taskCard.classList.add("active-task");
    activeTaskId = stableTaskIdFromCard(taskCard);
  } else {
    activeTaskId = "global";
  }

  // Update activeRoomId based on roomEl id
  if (roomEl.id) activeRoomId = roomEl.id;

  refreshThread(activeTaskId);
}

/* =========================
   INITIAL POSITIONS
   ========================= */

window.onload = () => {
  moveAgent(agents.coach, rooms.strategy);
  moveAgent(agents.builder, rooms.apps);
  moveAgent(agents.scout, rooms.jobs);
  moveAgent(agents.thinker, rooms.learning);
  refreshThread("global");
};

/* =========================
   TASK CARD CLICK HANDLER
   ========================= */

taskCards.forEach((card) => {
  card.addEventListener("click", () => {
    const assignedText = card.textContent || "";

    if (assignedText.includes("Builder")) moveAgent(agents.builder, rooms.apps, card);
    if (assignedText.includes("Scout")) moveAgent(agents.scout, rooms.jobs, card);
    if (assignedText.includes("Strategist")) moveAgent(agents.coach, rooms.strategy, card);
    if (assignedText.includes("Think")) moveAgent(agents.thinker, rooms.learning, card);
  });
});

/* =========================
   AI COMMAND CONNECTION
   ========================= */

const commandInput = document.getElementById("ai-command-input");
const commandSend = document.getElementById("ai-command-send");

async function sendToAI(message, taskId, forcedAgentName = "") {
  const agentName = forcedAgentName || getActiveAgentName();

  const response = await fetch(`${BACKEND_URL}/command`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      message,
      taskId: taskId || "global",
      agent: agentName,
    }),
  });

  if (!response.ok) throw new Error("Server error");
  return response.json();
}

commandSend.addEventListener("click", async () => {
  const text = commandInput.value.trim();
  const tid = activeTaskId || "global";

  if (!text) return;

  // Append user message to personal layer for personalization
  await appendMessageToBackend(tid, "user", "", text, "personal");
  await refreshThread(tid);

  try {
    const data = await sendToAI(text, tid);

    const replyAgent = data.agent || getActiveAgentName() || "Coach";
    const replyText = data.reply || data.message || "No reply returned.";

    await appendMessageToBackend(tid, "assistant", replyAgent, replyText, "personal");
    await refreshThread(tid);
  } catch (err) {
    console.error(err);
    await appendMessageToBackend(tid, "system", "System", "Error connecting to AI server.", "system");
    await refreshThread(tid);
  }

  commandInput.value = "";
});

commandInput.addEventListener("keypress", (e) => {
  if (e.key === "Enter") commandSend.click();
});

/* =========================
   DECISION BUTTONS
   ========================= */

const decisionButtons = document.querySelectorAll(".decision-btn");

async function updateTaskStatus(taskId, status) {
  const tid = taskId || "global";
  try {
    const res = await fetch(`${BACKEND_URL}/task/update`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ taskId: tid, status }),
    });

    if (res.status === 404) return false;

    const data = await res.json();
    return Boolean(data.success);
  } catch {
    return false;
  }
}

decisionButtons.forEach((btn) => {
  btn.addEventListener("click", async () => {
    const tid = activeTaskId || "global";
    const action = btn.dataset.action;
    if (!action) return;

    const taskText = getActiveTaskText();
    const activeAgent = getActiveAgentName();

    // Log the decision as a user action in personal layer
    await appendMessageToBackend(tid, "user", "", `Decision: ${action}`, "personal");
    await refreshThread(tid);

    // Store status update as role system (badge style) in global layer
    const ok = await updateTaskStatus(tid, action);
    await appendMessageToBackend(
      tid,
      "system",
      "System",
      ok ? `Task status updated to ${action}` : "Task status update failed or endpoint not available.",
      "global"
    );
    await refreshThread(tid);

    // Force commentary to come from the active agent, and include the task text
    try {
      const prompt =
        `Decision made: ${action}\n\n` +
        `Task:\n${taskText}\n\n` +
        `Reply as ${activeAgent}.` +
        ` Provide a short rationale, 3 concrete next steps, and 1 risk or unknown.`;

      const data = await sendToAI(prompt, tid, activeAgent);

      await appendMessageToBackend(
        tid,
        "assistant",
        data.agent || activeAgent,
        data.reply || "No reply returned.",
        "personal"
      );
      await refreshThread(tid);
    } catch {
      await appendMessageToBackend(tid, "system", "System", "Error generating decision commentary.", "global");
      await refreshThread(tid);
    }
  });
});
