const ThreadMessage = require("../models/threadMessage");

// Fetch messages by layer and id
exports.getThreadByLayer = async (req, res) => {
  const { layer, id } = req.params;
  if (!["global", "room", "personal"].includes(layer)) {
    return res.status(400).json({ error: "Invalid layer" });
  }
  try {
    const messages = await ThreadMessage.find({ layer, taskId: id }).sort({ createdAt: 1 });
    res.json(messages);
  } catch (err) {
    res.status(500).json({ error: "Failed to fetch thread messages" });
  }
};

// Append message with layer info
exports.appendMessage = async (req, res) => {
  const { taskId, role, agent, content, layer } = req.body;
  if (!taskId || !content) {
    return res.status(400).json({ error: "Missing taskId or content" });
  }
  const messageLayer = ["global", "room", "personal"].includes(layer) ? layer : "global";

  try {
    const msg = new ThreadMessage({
      taskId,
      role: role || "user",
      agent: agent || "",
      content,
      layer: messageLayer,
    });
    await msg.save();
    res.json({ success: true, message: "Message appended" });
  } catch (err) {
    res.status(500).json({ error: "Failed to append message" });
  }
