```js
const modelCostData = [
  { model: "gpt-4", costPer1KTokens: "$0.03", notes: "High quality, slower" },
  { model: "gpt-4-32k", costPer1KTokens: "$0.06", notes: "Extended context" },
  { model: "gpt-3.5-turbo", costPer1KTokens: "$0.002", notes: "Faster, cheaper" },
  { model: "gpt-3.5-turbo-16k", costPer1KTokens: "$0.004", notes: "Extended context" },
];

function renderModelCostPanel() {
  const panel = document.getElementById("model-cost-panel");
  let html = `<h3>Model Cost Comparison</h3><table><thead><tr><th>Model</th><th>Cost per 1K tokens</th><th>Notes</th></tr></thead><tbody>`;

  modelCostData.forEach(({ model, costPer1KTokens, notes }) => {
    html += `<tr><td>${model}</td><td>${costPer1KTokens}</td><td>${notes}</td></tr>`;
  });

  html += "</tbody></table>";
  panel.innerHTML = html;
}

function setupFeedbackForm() {
  const submitBtn = document.getElementById("submit-feedback");
  const feedbackText = document.getElementById("feedback-text");
  const feedbackRating = document.getElementById("feedback-rating");
  const feedbackMessage = document.getElementById("feedback-message");

  submitBtn.addEventListener("click", () => {
    const text = feedbackText.value.trim();
    const rating = feedbackRating.value;

    if (!text) {
      feedbackMessage.style.color = "red";
      feedbackMessage.textContent = "Please enter your comments.";
      return;
    }
    if (!rating) {
      feedbackMessage.style.color = "red";
      feedbackMessage.textContent = "Please select a rating.";
      return;
    }

    // Store feedback locally for now
    const feedbackEntry = { text, rating, timestamp: new Date().toISOString() };
    let feedbackList = JSON.parse(localStorage.getItem("modelCostFeedback") || "[]");
    feedbackList.push(feedbackEntry);
    localStorage.setItem("modelCostFeedback", JSON.stringify(feedbackList));

    feedbackMessage.style.color = "green";
    feedbackMessage.textContent = "Thank you for your feedback!";
    feedbackText.value = "";
    feedbackRating.value = "";
  });
}

window.addEventListener("DOMContentLoaded", () => {
  renderModelCostPanel();
  setupFeedbackForm();
});
